        margin: 0;
        min-height: 100vh;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 34rem),
          linear-gradient(135deg, var(--page-bg), #eef2ff);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--accent);
        border-radius: 0.75rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .page-shell {
        width: min(100% - 2rem, 760px);
        margin: 0 auto;
        padding: 4rem 0;
      }

      header {
        margin-bottom: 1.5rem;
        text-align: center;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-dark);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3.75rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 42rem;
        margin: 1rem auto 0;
        color: var(--text-muted);
        font-size: 1.08rem;
        line-height: 1.6;
      }

      .card {
        overflow: hidden;
        background: var(--surface);
        border: 1px solid rgba(203, 213, 225, 0.8);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
      }

      form {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      fieldset {
        min-width: 0;
        margin: 0;
        padding: 0;
        border: 0;
      }

      .form-field {
        display: grid;
        gap: 1rem;
      }

      legend {
        margin-bottom: 0.35rem;
        color: var(--text);
        font-size: 1.25rem;
        font-weight: 800;
        line-height: 1.3;
      }

      .field-hint {
        margin: 0;
        color: var(--text-muted);
        font-size: 0.98rem;
      }

      .radio-group {
        display: grid;
        gap: 0.85rem;
        margin-top: 0.35rem;
      }

      .radio-card {
        display: flex;
        align-items: center;
        gap: 0.9rem;
        min-width: 0;
        padding: 1rem;
        background: var(--surface-muted);
        border: 2px solid var(--border);
        border-radius: 1rem;
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background-color 160ms ease,
          transform 160ms ease;
      }

      .radio-card:hover {
        border-color: var(--accent);
        transform: translateY(-1px);
      }

      .radio-card input {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0;
        flex: 0 0 auto;
        accent-color: var(--accent);
      }

      .radio-card:has(input:checked) {
        background: #eff6ff;
        border-color: var(--accent);
      }

      .radio-card:has(input:focus-visible) {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--focus);
      }

      .radio-label {
        display: grid;
        gap: 0.15rem;
        min-width: 0;
      }

      .radio-title {
        font-weight: 800;
      }

      .radio-description {
        color: var(--text-muted);
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 1rem;
        flex-wrap: wrap;
        margin-top: 1.5rem;
        padding-top: 1.5rem;
        border-top: 1px solid #e2e8f0;
      }

      button {
        min-height: 2.75rem;
        padding: 0.8rem 1.2rem;
        color: #ffffff;
        background: var(--accent);
        border: 0;
        border-radius: 999px;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.26);
      }

      button:hover {
        background: var(--accent-dark);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-width: 0;
        margin: 0;
        color: var(--text-muted);
        font-weight: 700;
      }

      @media (max-width: 420px) {
        .page-shell {
          width: min(100% - 1rem, 760px);
          padding: 2rem 0;
        }

        form {
          padding: 1rem;
        }

        .radio-card {
          align-items: flex-start;
        }
      }

      @media (forced-colors: active) {
        .card,
        .radio-card,
        button {
          border: 2px solid ButtonBorder;
        }

        .radio-card:has(input:focus-visible),
        button:focus-visible,
        .skip-link:focus {
          outline: 3px solid ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main" class="page-shell">
      <header>
        <p class="eyebrow">Account settings</p>
        <h1>Notification Preferences</h1>
        <p class="intro">
          Choose the channel that works best for important product updates and
          account messages.
        </p>
      </header>

      <section class="card" aria-labelledby="preferences-heading">
        <form id="notification-form" novalidate>
          <h2 id="preferences-heading">Contact preference</h2>
          <div class="form-field">
            <fieldset aria-describedby="notification-hint">
              <legend>How do you prefer to receive notifications?</legend>
              <p id="notification-hint" class="field-hint">
                Select one option before submitting.
              </p>

              <div class="radio-group">
                <label class="radio-card" for="notification-email">
                  <input
                    id="notification-email"
                    type="radio"
                    name="notificationPreference"
                    value="Email"
                    required
                  >
                  <span class="radio-label">
                    <span class="radio-title">Email</span>
                    <span class="radio-description">
                      Receive updates in your inbox.
                    </span>
                  </span>
                </label>

                <label class="radio-card" for="notification-sms">
                  <input
                    id="notification-sms"
                    type="radio"
                    name="notificationPreference"
                    value="SMS"
                    required
                  >
                  <span class="radio-label">
                    <span class="radio-title">SMS</span>
                    <span class="radio-description">
                      Get short alerts by text message.
                    </span>
                  </span>
                </label>

                <label class="radio-card" for="notification-push">
                  <input
                    id="notification-push"
                    type="radio"
                    name="notificationPreference"
                    value="Push Notifications"
                    required
                  >
                  <span class="radio-label">
                    <span class="radio-title">Push Notifications</span>
                    <span class="radio-description">
                      See timely alerts on your device.
                    </span>
                  </span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Save preference</button>
            <p id="form-status" class="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const choices = ["Email", "SMS", "Push Notifications"];

      function NotificationPreferenceForm(root) {
        const form = root.querySelector("#notification-form");
        const status = root.querySelector("#form-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          const selected = form.querySelector(
            'input[name="notificationPreference"]:checked'
          );

          if (!selected) {
            status.textContent = "Choose Email, SMS, or Push Notifications.";
            form.querySelector('input[name="notificationPreference"]').focus();
            return;
          }

          status.textContent = `Preference saved: ${selected.value}.`;
        });
      }

      function App() {
        NotificationPreferenceForm(document);
      }

      App();
    </script>
  </body>
</html>
